package main
import("bufio";"context";"encoding/csv";"io";"log";"os";"strings";"github.com/wuangmmo/sodienthoai-platform/apps/api/internal/database";"github.com/wuangmmo/sodienthoai-platform/apps/api/internal/phone")
func main(){dbURL:=os.Getenv("DATABASE_URL");if dbURL==""{log.Fatal("DATABASE_URL required")};if len(os.Args)<2{log.Fatal("usage: importphones <csv>")};ctx:=context.Background();db,err:=database.Open(ctx,dbURL);if err!=nil{log.Fatal(err)};defer db.Close();f,err:=os.Open(os.Args[1]);if err!=nil{log.Fatal(err)};defer f.Close();r:=csv.NewReader(bufio.NewReaderSize(f,1<<20));repo:=phone.Repository{DB:db};batch:=make([]phone.ImportRow,0,2000);var accepted,rejected int64
 flush:=func(){if len(batch)==0{return};a,b,e:=repo.ImportRows(ctx,os.Args[1],batch);if e!=nil{log.Fatal(e)};accepted+=a;rejected+=b;batch=batch[:0]}
 for{row,e:=r.Read();if e==io.EOF{break};if e!=nil{rejected++;continue};if len(row)<4{rejected++;continue};batch=append(batch,phone.ImportRow{CountryCode:strings.ToUpper(strings.TrimSpace(row[0])),CallingCode:strings.TrimSpace(row[1]),NationalNumber:strings.TrimSpace(row[2]),E164:strings.TrimSpace(row[3]),NumberType:func()string{if len(row)>4{return strings.TrimSpace(row[4])};return ""}()});if len(batch)>=2000{flush()}};flush();log.Printf("import completed accepted=%d rejected=%d",accepted,rejected)}
